<template>
  <div class="app-container"><ModuleHeader title="文件记录" description="只读查看设备上传的图片、音频和视频记录；文件删除与上传不在后台开放。"/><el-form class="search-form" :inline="true" :model="query"><el-form-item label="文件名称"><el-input v-model="query.fileName" clearable placeholder="名称关键词" @keyup.enter="search"/></el-form-item><el-form-item label="文件类型"><el-select v-model="query.fileType" clearable class="w-140" placeholder="全部"><el-option label="图片" value="image"/><el-option label="视频" value="video"/><el-option label="音频" value="audio"/></el-select></el-form-item><el-form-item label="设备"><el-input v-model="query.device" clearable placeholder="设备编号"/></el-form-item><el-form-item label="人员"><el-input v-model="query.userName" clearable placeholder="人员姓名"/></el-form-item><el-form-item label="上传日期"><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="search">查询</el-button><el-button icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form><div class="page-toolbar"><el-button icon="Download" @click="doExport">导出筛选结果</el-button></div><el-table v-loading="loading" class="custom-table" :data="list"><template #empty><BrandedEmpty compact description="暂无文件记录"/></template><el-table-column label="文件名称" prop="fileName" min-width="230" show-overflow-tooltip/><el-table-column label="类型" width="100"><template #default="s"><el-tag effect="plain" size="small">{{ typeLabel(s.row.fileType) }}</el-tag></template></el-table-column><el-table-column label="设备" prop="hatNumber" min-width="140"/><el-table-column label="人员" prop="userName" min-width="120"/><el-table-column label="大小" width="110"><template #default="s">{{ sizeLabel(s.row.fileSize) }}</template></el-table-column><el-table-column label="上传时间" prop="uploadTime" width="190"/><el-table-column label="操作" width="150" fixed="right"><template #default="s"><el-button link type="primary" @click="preview(s.row)">预览</el-button><el-button link type="primary" @click="downloadRow(s.row)">下载</el-button></template></el-table-column></el-table><pagination v-show="total>0" v-model:page="query.current" v-model:limit="query.size" :total="total" @pagination="load"/><el-dialog v-model="previewOpen" :title="current.fileName||'文件预览'" width="760px" @closed="clearPreview"><div v-loading="previewLoading" class="preview-box"><el-image v-if="previewUrl&&isImage(current)" :src="previewUrl" fit="contain" :preview-src-list="[previewUrl]"/><video v-else-if="previewUrl&&current.fileType==='video'" :src="previewUrl" controls preload="metadata"></video><audio v-else-if="previewUrl&&current.fileType==='audio'" :src="previewUrl" controls></audio><BrandedEmpty v-else-if="!previewLoading" compact :description="previewUrl?'此文件类型不支持在线预览':'文件预览加载失败'"/></div></el-dialog></div>
</template>
<script setup>
import {saveAs} from 'file-saver';import {listFiles,downloadFileRecord} from '@/api/wear/files';import {downloadExport} from '@/api/wear/admin';const loading=ref(false);const list=ref([]);const total=ref(0);const dateRange=ref([]);const query=reactive({current:1,size:10,fileName:'',fileType:'',device:'',userName:'',uploadTimeFrom:'',uploadTimeTo:''});const previewOpen=ref(false);const previewLoading=ref(false);const previewUrl=ref('');const current=ref({});function unwrap(r){return r?.data!==undefined?r.data:r}function syncDates(){query.uploadTimeFrom=dateRange.value?.[0]||'';query.uploadTimeTo=dateRange.value?.[1]||''}function load(){syncDates();loading.value=true;listFiles(query).then(r=>{const p=unwrap(r)||{};list.value=p.records||[];total.value=p.total||0}).finally(()=>{loading.value=false})}function search(){query.current=1;load()}function reset(){Object.assign(query,{current:1,fileName:'',fileType:'',device:'',userName:'',uploadTimeFrom:'',uploadTimeTo:''});dateRange.value=[];load()}function typeLabel(v){return {image:'图片',pic:'图片',video:'视频',audio:'音频'}[v]||v||'—'}function isImage(row){return row.fileType==='image'||row.fileType==='pic'}function mimeOf(row){return isImage(row)?'image/*':row.fileType==='video'?'video/mp4':row.fileType==='audio'?'audio/mpeg':'application/octet-stream'}function sizeLabel(v){const n=Number(v||0);return n>=1048576?`${(n/1048576).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:n?`${n} B`:'—'}function preview(row){clearPreview();current.value=row;previewOpen.value=true;previewLoading.value=true;downloadFileRecord(row.id).then(data=>{previewUrl.value=URL.createObjectURL(new Blob([data],{type:mimeOf(row)}))}).finally(()=>{previewLoading.value=false})}function clearPreview(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=''}function downloadRow(row){downloadFileRecord(row.id).then(data=>saveAs(new Blob([data]),row.fileName||'文件'))}function doExport(){syncDates();downloadExport('files',{...query},'文件记录.xlsx')}function onSiteChanged(){search()}onMounted(()=>{load();window.addEventListener('site-changed',onSiteChanged)});onUnmounted(()=>{clearPreview();window.removeEventListener('site-changed',onSiteChanged)})
</script><style scoped>.w-140{width:140px}.preview-box{display:grid;place-items:center;min-height:300px;background:#0e1823}.preview-box :deep(img),.preview-box video{max-width:100%;max-height:65vh}.preview-box audio{width:min(520px,90%)}</style>
